public class LongWordFinderCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(LongWordFinder impl) {
        try {
            return LongWordFinderChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectFinder()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectFinder()));
        check("rejects the null returned instead of Optional.empty()", false, verdict(new NullReturningFinder()));
        check("rejects the >= that should have been >", false, verdict(new InclusiveFinder()));
        check("rejects the version that returns the last match instead of the first", false, verdict(new LastMatchFinder()));
        check("rejects the crash on an empty list", false, verdict(new CrashOnEmptyFinder()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectFinder implements LongWordFinder {
    public java.util.Optional<String> firstLongerThan(java.util.List<String> words, int n) {
        for (String word : words) {
            if (word.length() > n) return java.util.Optional.of(word);
        }
        return java.util.Optional.empty();
    }
}

class AlsoCorrectFinder implements LongWordFinder {
    public java.util.Optional<String> firstLongerThan(java.util.List<String> words, int n) {
        return words.stream().filter(word -> word.length() > n).findFirst();
    }
}

class NullReturningFinder implements LongWordFinder {
    public java.util.Optional<String> firstLongerThan(java.util.List<String> words, int n) {
        for (String word : words) {
            if (word.length() > n) return java.util.Optional.of(word);
        }
        return null;
    }
}

class InclusiveFinder implements LongWordFinder {
    public java.util.Optional<String> firstLongerThan(java.util.List<String> words, int n) {
        for (String word : words) {
            if (word.length() >= n) return java.util.Optional.of(word);
        }
        return java.util.Optional.empty();
    }
}

class LastMatchFinder implements LongWordFinder {
    public java.util.Optional<String> firstLongerThan(java.util.List<String> words, int n) {
        java.util.Optional<String> answer = java.util.Optional.empty();
        for (String word : words) {
            if (word.length() > n) answer = java.util.Optional.of(word);
        }
        return answer;
    }
}

class CrashOnEmptyFinder implements LongWordFinder {
    public java.util.Optional<String> firstLongerThan(java.util.List<String> words, int n) {
        if (words.get(0).length() > n) return java.util.Optional.of(words.get(0));
        for (String word : words) {
            if (word.length() > n) return java.util.Optional.of(word);
        }
        return java.util.Optional.empty();
    }
}

