/**
 * TASK: Write the checks that decide whether a LongWordFinder is correct.
 *
 *   firstLongerThan(words, n) returns the FIRST word with MORE than n letters,
 *   wrapped in an Optional. When there is no such word it returns
 *   Optional.empty() -- never null, and never an Optional holding null.
 *   Examples: firstLongerThan(["hi", "there", "friend"], 3) -> Optional[there]
 *             firstLongerThan(["hi", "yo"], 3)              -> Optional.empty
 *             firstLongerThan(["abc"], 3)                   -> Optional.empty  (3 is not MORE than 3)
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
import java.util.List;
import java.util.Optional;

interface LongWordFinder {
    /* Provided -- do not edit. */
    Optional<String> firstLongerThan(List<String> words, int n);
}

public class LongWordFinderChecker {

    public static boolean isCorrect(LongWordFinder impl) {
        try {
            java.util.Optional<String> found =
                    impl.firstLongerThan(java.util.List.of("hi", "there", "friend"), 3);
            if (found == null || found.isEmpty()) return false;
            if (!"there".equals(found.get())) return false;

            java.util.Optional<String> none =
                    impl.firstLongerThan(java.util.List.of("hi", "yo"), 3);
            if (none == null || none.isPresent()) return false;

            java.util.Optional<String> exact =
                    impl.firstLongerThan(java.util.List.of("abc"), 3);
            if (exact == null || exact.isPresent()) return false;

            java.util.Optional<String> empty =
                    impl.firstLongerThan(java.util.List.of(), 1);
            if (empty == null || empty.isPresent()) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
